'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<span class="icon">${window.LUMEN_ICONS[n]||''}</span>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=window.LUMEN_ICONS[e.dataset.icon]||'');
const project='https://lumen-fix.universalgravity.org/#project/c4ee827c897a4960a6eb9131207f5a6e';
const versions=[{id:'effects',name:'Русский · с эффектами',detail:'Русская озвучка · приближения и переходы',poster:'effects',date:'17 сентября · версия 03'},{id:'russian',name:'Русский · без эффектов',detail:'Русская озвучка · чистый монтаж',poster:'original',date:'17 сентября · версия 02'},{id:'source',name:'Исходник',detail:'Оригинальный звук · встроенные надписи',poster:'original',date:'Исходный материал'}];
const scenes=[['Бассейн у порога',0,8.5,'effects'],['Прыжок в бассейн',8.5,23,'original'],['Прямой доступ',23,44.5,'original'],['Приватность',44.5,58,'interior'],['Сравнение проектов',58,150.5,'interior'],['Каждый день',150.5,160.86,'ending']];
const tasks=[['edit','Scissors','Монтаж'],['subtitles','Captions','Субтитры'],['audio','AudioLines','Звук'],['effects','Sparkles','Эффекты'],['materials','FolderOpen','Материалы']];
let state={task:'edit',scene:0,version:'effects',scenario:'ready',changes:{},zoom:1,caption:false,language:'ru',music:null,prompt:'',scope:'scene'},returnVersion='effects',opener=null,musicURL=null;
const video=$('#video');
const time=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
function dirty(key,value){state.changes[key]=value;state.scenario='dirty';footer();$('#canvas-badge').textContent='Черновой просмотр · приблизительно'}
function footer(){const s=state.scenario;$('#scenario').value=s;const descriptions={ready:['CircleCheck','Версия готова','Можно смотреть и скачивать'],dirty:['SlidersHorizontal','Есть изменения',`${Object.keys(state.changes).length||1} правки · готовое видео сохранено`],rendering:['LoaderCircle','Собираем новую версию','Демонстрация состояния · предыдущая доступна'],error:['CircleHelp','Не удалось собрать видео','Правки сохранены · готовая версия доступна']};const [i,h,p]=descriptions[s];$('#action-status').className=`action-status ${s}`;$('#action-status').innerHTML=`${icon(i)}<div><strong>${h}</strong><span>${p}</span></div>`;$('#header-status').innerHTML=icon(i)+h;$('#action-buttons').innerHTML=s==='ready'?`<button class="button primary" data-action="export">${icon('Download')}Скачать видео</button>`:s==='dirty'?`<button class="button" data-action="undo">${icon('Undo2')}<span>Отменить</span></button><button class="button primary" data-action="review">Проверить изменения ${icon('ArrowRight')}</button>`:s==='error'?`<button class="button" data-action="export">Скачать готовую</button><button class="button primary" data-action="render">Повторить</button>`:`<button class="button" data-action="versions">Готовые версии</button>`;}
function render(){ $('#tools').innerHTML=tasks.map(([id,i,n])=>`<button class="tool-button" data-action="task" data-task="${id}" aria-pressed="${state.task===id}">${icon(i)}<span>${n}</span></button>`).join('')+`<button class="tool-button rail-help" data-action="about">${icon('CircleHelp')}<span>Помощь</span></button>`;$('#scenes').innerHTML=scenes.map(([n,start,end,p],i)=>`<button class="scene-card ${state.scene===i?'selected':''}" aria-pressed="${state.scene===i}" data-action="scene" data-scene="${i}"><div class="scene-thumb"><img src="assets/${p}-poster.jpg" alt=""><span>${String(i+1).padStart(2,'0')}</span></div><strong>${n}</strong><small>${time(start)}–${time(end)}</small></button>`).join('');inspector();footer();}
function selected(){const [n,a,b,p]=scenes[state.scene];return `<div class="selected-scene"><img src="assets/${p}-poster.jpg" alt=""><div><strong>${n}</strong><span>${time(a)}–${time(b)} · ${(b-a).toFixed(1)} с</span></div></div>`}
function ai(){return `<section class="ai-box"><div class="ai-heading">${icon('WandSparkles')}<strong>Помочь с монтажом</strong><span class="badge">AI</span></div><label for="scope">Что изменить</label><select id="scope"><option value="scene" ${state.scope==='scene'?'selected':''}>Выбранную сцену</option><option value="all" ${state.scope==='all'?'selected':''}>Весь ролик</option></select><label for="prompt">Ваше пожелание</label><textarea id="prompt" rows="3" placeholder="Например: плавно приблизить кадр к ведущему">${esc(state.prompt)}</textarea><div class="chip-row"><button class="chip" data-action="example">Плавное приближение</button></div><div class="ai-actions"><span>В макете — пример ответа</span><button class="button soft" data-action="suggest">Предложить ${icon('ArrowRight')}</button></div><div id="proposal"></div></section>`}
function inspector(){const task=tasks.find(t=>t[0]===state.task);$('#inspector-title').textContent=task[2];$('#inspector-symbol').innerHTML=icon(task[1]);$('#inspector-kicker').textContent=state.task==='edit'||state.task==='effects'?`СЦЕНА ${String(state.scene+1).padStart(2,'0')} / 06`:'НАСТРОЙКИ РОЛИКА';let content='';
if(state.task==='edit')content=`${selected()}<section class="inspector-section"><div class="label-row"><label for="zoom">Крупность кадра</label><output id="zoom-value">${state.zoom.toFixed(2)}×</output></div><input id="zoom" type="range" min="1" max="1.3" step="0.01" value="${state.zoom}"><div class="range-labels"><span>Исходный кадр</span><span>Ближе</span></div><p class="field-hint">Масштаб в макете показан приблизительно. Исходник сохраняется.</p><div class="preset-grid"><button class="preset" data-action="effect" data-effect="Плавное приближение">${icon('ZoomIn')}Плавное приближение</button><button class="preset" data-action="reset-zoom">${icon('RotateCcw')}Без приближения</button></div></section><section class="inspector-section"><label for="transition">Переход к следующей сцене</label><select id="transition"><option>Прямая склейка</option><option>Плавное растворение</option><option>Сдвиг</option></select></section>${ai()}`;
if(state.task==='subtitles')content=`<section class="subtitle-source"><div class="label-row"><strong>Надписи в исходнике</strong>${icon('LockKeyhole')}</div><span class="badge">Часть изображения</span><p>Китайский и английский текст уже записан в видео. Переключатель субтитров его не уберёт.</p><button class="text-button" data-action="source-text">Как убрать эти надписи ${icon('ArrowUpRight')}</button></section><section class="inspector-section"><div class="switch-row"><div><strong>Новые субтитры</strong><p>Отдельный слой поверх видео</p></div><button class="toggle" role="switch" aria-label="Новые субтитры" aria-checked="${state.caption}" data-action="caption"></button></div><label for="caption-text">Пример текста</label><input id="caption-text" type="text" value="${esc($('#added-caption').textContent)}"><p class="field-hint">Демонстрационный слой. Встроенные титры и три надписи готовой версии сохраняются.</p></section><details class="transcript"><summary>Расшифровка речи</summary><p class="field-hint">Текст для чтения. Не отображается в кадре.</p><div class="line"><time>0:00</time><span>Бассейн прямо у порога квартиры.</span></div><div class="line"><time>0:23</time><span>Прямой доступ к воде — каждый день.</span></div><p class="field-hint">Сокращённый пример для макета.</p></details>`;
if(state.task==='audio')content=`<section class="inspector-section"><div class="label-row"><strong>Озвучка</strong><span class="badge">Русский · готово</span></div><label for="voice-language">Язык озвучки</label><select id="voice-language"><option value="ru" ${state.language==='ru'?'selected':''}>Русский</option><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="zh" ${state.language==='zh'?'selected':''}>中文</option></select><label for="voice">Голос</label><select id="voice"><option>Мужской · спокойный</option><option>Женский · выразительный</option></select><button class="button full" data-action="voice-preview">${icon('Play')}Послушать готовую озвучку</button><p class="field-hint">В макете доступен русский пример из test11.</p><div class="info-box warning">Новая озвучка заменяет исходную звуковую дорожку целиком, включая музыку и фон.</div><button class="button primary full" data-action="voice-apply">Изменить озвучку</button></section><section class="inspector-section"><div class="label-row"><strong>Музыка</strong>${icon('Music2')}</div>${state.music?`<div class="audio-item"><strong>${esc(state.music.name)}</strong><audio controls src="${musicURL}" style="width:100%"></audio><button class="text-button" data-action="remove-music">Убрать музыку</button></div>`:`<div class="empty-music">${icon('Music2')}<strong>Добавьте свой трек</strong><p>После загрузки можно выбрать музыку для ролика.</p></div>`}<label class="button full" for="music-file">${icon('Upload')}Выбрать аудиофайл</label><input id="music-file" type="file" accept="audio/*" hidden><p class="field-hint">Файл остаётся только в этом браузере.</p></section>`;
if(state.task==='effects')content=`${selected()}<section class="inspector-section"><p class="field-hint">Выберите заметный эффект для текущей сцены. Готовая версия останется доступна.</p><div class="effect-grid">${[['Плавное приближение','ZoomIn'],['Растворение','Layers'],['Сдвиг','ArrowRight'],['Акцент текстом','Type']].map(([n,i])=>`<button class="effect-card" data-action="effect" data-effect="${n}"><div class="effect-preview">${icon(i)}</div><strong>${n}</strong><small>Применить к сцене ${state.scene+1}</small></button>`).join('')}</div><div class="info-box">В макете можно увидеть приближение и текст. Переходы добавляются в список правок для проверки.</div></section>${ai()}`;
if(state.task==='materials')content=`<section class="inspector-section"><strong>Материалы проекта</strong><p class="field-hint">Исходник всегда доступен отдельно от обработанных версий.</p><div class="material-grid"><button class="material-card" data-action="version" data-version="source"><img src="assets/original-poster.jpg" alt="Исходное видео у бассейна"><strong>Исходное видео</strong><small>9:16 · 2:42 · оригинальный звук</small></button></div><button class="button full" data-action="versions">${icon('History')}Посмотреть все версии</button><div class="info-box">Новые материалы загружаются в рабочем проекте. Здесь показана организация библиотеки.</div><a class="button full" href="${project}" target="_blank" rel="noopener">Открыть рабочий проект ${icon('ArrowUpRight')}</a></section>`;
$('#inspector-content').innerHTML=content;}
function modal(title,body,footer=''){opener=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Закрыть">${icon('X')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal()}
function close(){ $('#dialog').close();opener?.focus();}
function chooseVersion(id){state.version=id;const v=versions.find(x=>x.id===id);video.src=`assets/${id}.mp4`;video.poster=`assets/${v.poster}-poster.jpg`;$('#version-label').textContent=v.name;$('#canvas-badge').textContent=id==='source'?'Исходный материал':'Готовая версия';$('#compare-label').textContent=id==='source'?'Вернуться к версии':'Сравнить с исходником';$('#video-frame').style.transform='';$('#added-caption').hidden=true;$('.track-summary').innerHTML=`<span><i class="track-line voice-line"></i>${id==='source'?'Оригинальный звук':'Русская озвучка'}</span><span><i class="track-line text-line"></i>${id==='effects'?'3 надписи':'Встроенные надписи'}</span>`;}
function exportVersion(id=state.version){const v=versions.find(x=>x.id===id);modal('Скачать видео',`<div class="export-summary"><img src="assets/${v.poster}-poster.jpg" alt=""><div><strong>${v.name}</strong><p>test11 · MP4 · вертикальное видео</p></div></div><div class="info-box">Выбрана именно эта версия: <strong>${v.name}</strong>.</div><p class="prototype-note">Это дизайн-прототип. Настоящее скачивание доступно в рабочем проекте; здесь файл не пересоздаётся.</p>`,`<button class="button" data-action="close">Закрыть</button><a class="button primary" href="${project}" target="_blank" rel="noopener">Открыть рабочий проект ${icon('ArrowUpRight')}</a>`)}
function effect(name){if(name.includes('приближение')){state.zoom=1.2;$('#video-frame').style.transform='scale(1.2)'}if(name==='Акцент текстом'){state.caption=true;$('#added-caption').hidden=false}dirty(`Сцена ${state.scene+1}`,name);inspector();toast(`${name} — добавлено в черновик`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.tagName==='A')e.preventDefault();switch(a){case 'task':state.task=b.dataset.task;render();break;case 'scene':state.scene=+b.dataset.scene;video.currentTime=state.version==='source'?(state.scene===0?14.5:state.scene===1?0:scenes[state.scene][1]):scenes[state.scene][1];render();break;case 'voice-preview':if(state.version==='source')chooseVersion('russian');try{await video.play()}catch{toast('Не удалось запустить пример')}break;case 'play':if(video.paused){try{await video.play()}catch{toast('Не удалось запустить предпросмотр')}}else video.pause();break;case 'mute':video.muted=!video.muted;b.setAttribute('aria-pressed',video.muted);b.setAttribute('aria-label',video.muted?'Включить звук':'Выключить звук');break;case 'expand':try{await $('#stage').requestFullscreen()}catch{toast('Полноэкранный режим недоступен')}break;case 'compare':if(state.version==='source')chooseVersion(returnVersion);else{returnVersion=state.version;chooseVersion('source')}break;case 'versions':modal('Версии ролика',`<p class="field-hint">Каждая версия хранится отдельно. Выберите, что смотреть или скачивать.</p>${versions.map(v=>`<div class="version-item ${v.id===state.version?'current':''}"><img src="assets/${v.poster}-poster.jpg" alt=""><div class="version-info"><small>${v.date}</small><strong>${v.name}</strong><p>${v.detail}</p></div><div class="version-actions"><button class="icon-button" data-action="version" data-version="${v.id}" aria-label="Смотреть: ${v.name}">${icon('Play')}</button><button class="icon-button" data-action="export" data-version="${v.id}" aria-label="Скачать: ${v.name}">${icon('Download')}</button></div></div>`).join('')}`);break;case 'version':chooseVersion(b.dataset.version);if($('#dialog').open)close();break;case 'export':exportVersion(b.dataset.version);break;case 'close':close();break;case 'caption':state.caption=!state.caption;$('#added-caption').hidden=!state.caption;dirty('Новые субтитры',state.caption?'Включены':'Выключены');inspector();break;case 'source-text':modal('Надписи уже в изображении',`<p>Китайские и английские надписи встроены в исходный видеофайл. Отключение новых субтитров их не удаляет.</p><p>Лучший вариант — загрузить исходник без текста. Кадрирование может скрыть часть надписей, но также обрежет изображение.</p><div class="info-box">Три русские надписи готовой версии с эффектами тоже уже записаны в этот файл. Для версии без них выберите «Русский · без эффектов».</div>`,`<button class="button" data-action="version" data-version="russian">Смотреть без эффектов</button><button class="button primary" data-action="crop">Настроить кадр</button>`);break;case 'crop':close();state.task='edit';render();$('#zoom').focus();break;case 'effect':effect(b.dataset.effect);break;case 'reset-zoom':state.zoom=1;$('#video-frame').style.transform='';dirty('Крупность кадра','1.00×');inspector();break;case 'example':state.prompt='Плавно приблизить кадр к ведущему на 20%';$('#prompt').value=state.prompt;$('#prompt').focus();break;case 'suggest':if(state.prompt.trim().length<3){toast('Опишите, что должно измениться');$('#prompt').focus();return}$('#proposal').innerHTML=`<div class="proposal"><strong>Пример предложения</strong><p>Плавное приближение на 20%. Область: ${state.scope==='all'?'весь ролик':'сцена '+(state.scene+1)}.</p><p class="field-hint">Заранее подготовленный пример, AI не запускался.</p><button class="button soft" data-action="apply-proposal">Применить к черновику</button></div>`;break;case 'apply-proposal':effect('Плавное приближение');if(state.scope==='all')dirty('Весь ролик','Приближение на 20%');break;case 'voice-apply':dirty('Озвучка',`${$('#voice-language').selectedOptions[0].text} · ${$('#voice').value}`);toast('Озвучка добавлена в список правок. Генерация не запускалась.');break;case 'remove-music':if(musicURL)URL.revokeObjectURL(musicURL);state.music=null;musicURL=null;dirty('Музыка','Убрана');inspector();break;case 'undo':if(musicURL)URL.revokeObjectURL(musicURL);musicURL=null;state.music=null;state.language='ru';state.changes={};state.scenario='ready';state.zoom=1;state.caption=false;$('#video-frame').style.transform='';$('#added-caption').hidden=true;$('#canvas-badge').textContent=state.version==='source'?'Исходный материал':'Готовая версия';render();toast('Правки черновика отменены');break;case 'review':modal('Проверьте изменения',`<p>Новая версия будет создана отдельно. Текущий готовый ролик сохранится.</p>${Object.entries(state.changes).map(([k,v])=>`<div class="review-row"><strong>${esc(k)}</strong><span>${esc(v)}</span></div>`).join('')}<label class="review-check"><input id="review-check" type="checkbox"> Я проверил изменения</label><p class="prototype-note">Кнопка покажет состояние сборки. Реальный рендер и платные запросы не запускаются.</p>`,`<button class="button" data-action="close">Вернуться</button><button class="button primary" data-action="render" id="render-button" disabled>Создать версию</button>`);break;case 'render':if($('#dialog').open)close();state.scenario='rendering';footer();toast('Демонстрация сборки. Переключить результат можно в верхней панели.');break;case 'about':modal('Рабочее пространство Lumen',`<p>Кликабельный дизайн-прототип на реальных материалах test11.</p><p>Один плеер, отдельные версии, инструменты по задачам и проверка правок перед созданием видео.</p><p>Состояния «Есть правки», «Сборка» и «Ошибка» переключаются в верхней панели. Изменения живут только до перезагрузки страницы. AI, рендер и API проекта не вызываются.</p><a class="button" href="${project}" target="_blank" rel="noopener">Открыть рабочий проект</a>`);break;}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='zoom'){state.zoom=+t.value;$('#zoom-value').textContent=state.zoom.toFixed(2)+'×';$('#video-frame').style.transform=`scale(${state.zoom})`;dirty('Крупность кадра',state.zoom.toFixed(2)+'×')}if(t.id==='prompt')state.prompt=t.value;if(t.id==='caption-text'){$('#added-caption').textContent=t.value;dirty('Текст субтитров',t.value)}if(t.id==='seek')video.currentTime=+t.value;});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='scenario'){state.scenario=t.value;if(t.value==='dirty'&&!Object.keys(state.changes).length)state.changes['Сцена 1']='Пример: плавное приближение';footer()}if(t.id==='scope')state.scope=t.value;if(t.id==='voice-language')state.language=t.value;if(t.id==='transition')dirty(`Переход · сцена ${state.scene+1}`,t.value);if(t.id==='review-check')$('#render-button').disabled=!t.checked;if(t.id==='music-file'&&t.files[0]){if(musicURL)URL.revokeObjectURL(musicURL);state.music=t.files[0];musicURL=URL.createObjectURL(state.music);dirty('Музыка',state.music.name);inspector()}});
video.addEventListener('loadedmetadata',()=>{$('#duration').textContent=time(video.duration);$('#seek').max=video.duration});video.addEventListener('timeupdate',()=>{$('#elapsed').textContent=time(video.currentTime);$('#seek').value=video.currentTime});
function playback(){ $('#stage-play').hidden=!video.paused;$('#play-button').innerHTML=icon(video.paused?'Play':'Pause');$('#play-button').setAttribute('aria-label',video.paused?'Воспроизвести видео':'Пауза');}
video.addEventListener('play',playback);video.addEventListener('pause',playback);video.addEventListener('emptied',playback);$('#dialog').addEventListener('close',()=>opener?.focus());
render();
